'use client'

import type { ReactNode } from 'react'

interface LogoProps {
  onScrollToTop?: () => void
}

/**
 * Logo — renders the Airbnb logo (Bélo mark + lowercase "airbnb")
 * matching the reference screenshot with brand coral red (#FF385C).
 */
export function Logo({ onScrollToTop }: LogoProps): ReactNode {
  const handleClick = () => {
    if (onScrollToTop) {
      onScrollToTop()
    } else {
      window.scrollTo({ top: 0, behavior: 'smooth' })
    }
  }

  return (
    <button
      type="button"
      onClick={handleClick}
      aria-label="Airbnb homepage"
      className="desktop-header-logo-btn"
    >
      <img
        src="/airbnb-logo.png"
        alt="Airbnb"
        className="desktop-header-logo-img"
        loading="eager"
      />
    </button>
  )
}
